INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(42811, 'Proverbs 24:3', 'Proverbs', 24, 3, 'یو کور د حکمت په بنیاد ودانیږي او د پوهې په وسیله هغه ټینګ ودریږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_3.mp3', '', 1761754199, 1761754199),
(42812, 'Proverbs 24:4', 'Proverbs', 24, 4, 'او کوټې یې د علم په وسیله د ښکلو او قیمتي خزانو نه ډکیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_4.mp3', '', 1761754199, 1761754199),
(42813, 'Proverbs 24:5', 'Proverbs', 24, 5, 'د حکمت د خاوند قدرت ډېریږي او د عالم قوت نور هم زیاتیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_5.mp3', '', 1761754199, 1761754199),
(42814, 'Proverbs 24:6', 'Proverbs', 24, 6, 'له ښو مشورو پرته جنګ ته مه ځه ډېر مشوره ورکوونکي د بریالیتوب سبب ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_6.mp3', '', 1761754199, 1761754199),
(42815, 'Proverbs 24:7', 'Proverbs', 24, 7, 'جاهل انسان د حکمت لوړ مقام ته نه شي رسېدلی او په جرګه کې خپله خوله نه شي خلاصولی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_7.mp3', '', 1761754199, 1761754199),
(42816, 'Proverbs 24:8', 'Proverbs', 24, 8, 'څوک چې بدې نقشې جوړوي نو د فرېبکار په نوم به مشهور شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_8.mp3', '', 1761754199, 1761754199),
(42817, 'Proverbs 24:9', 'Proverbs', 24, 9, 'د جاهلانو نقشې د ګناه نه ډکې وي او د ملنډو وهونکو نه خلک کرکه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_9.mp3', '', 1761754199, 1761754199),
(42818, 'Proverbs 24:10', 'Proverbs', 24, 10, 'که د سختۍ په وخت کې خپل همت له لاسه ورکړې نو ته بیا ډېر کمزوری انسان یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_10.mp3', '', 1761754199, 1761754199),
(42819, 'Proverbs 24:11', 'Proverbs', 24, 11, 'د هغه چا په خلاصون کې سستي مه کوه چې د مرګ په لور راښکل کیږي او هغوی وژغوره چې حلالېدو ته وړل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_11.mp3', '', 1761754199, 1761754199),
(42820, 'Proverbs 24:12', 'Proverbs', 24, 12, 'که ته وایې چې مونږ له دې نه خبر نه وو نو د زړونو د رازونو قضاوت کوونکی دې ته پام نه کوي؟ هغه چې ستا د ژوند حفاظت کوي، په دې به پوه نه شي؟ هغه به د هرچا د عمل سره سم بدل ورنه کړي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_12.mp3', '', 1761754199, 1761754199),
(42821, 'Proverbs 24:13', 'Proverbs', 24, 13, 'ای زما زویه! نو شات خوره، ځکه چې دا ښه شی دی او د مچیو د چک سوچه شات به ستا خوله خوږه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_13.mp3', '', 1761754199, 1761754199),
(42822, 'Proverbs 24:14', 'Proverbs', 24, 14, 'نو همدا شان حکمت هم ستا د روح دپاره خوږ دی. که ته یې حاصل کړې نو په راتلونکې کې به ستا دپاره پوره هیله وي او هېڅکله به ستا هیلې پای ته ونه رسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_14.mp3', '', 1761754199, 1761754199),
(42823, 'Proverbs 24:15', 'Proverbs', 24, 15, 'د بدکارانو په شان مه اوسه چې د نېکانو د کور په خلاف په کمین کې ناست وي ترڅو د هغوی د اوسېدلو کور لوټ او تالا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_15.mp3', '', 1761754199, 1761754199),
(42824, 'Proverbs 24:16', 'Proverbs', 24, 16, 'که نېک انسان حتی اووه وارې ولویږي خو بیاهم پاڅیږي خو بدکاران په بدۍ او بلا اخته کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_16.mp3', '', 1761754199, 1761754199),
(42825, 'Proverbs 24:17', 'Proverbs', 24, 17, 'کله چې ستا دښمن له پښو راولویږي خوند ترې مه اخله او که راغورځیږي نو خپل زړه دې مه خوشحالوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_17.mp3', '', 1761754199, 1761754199),
(42826, 'Proverbs 24:18', 'Proverbs', 24, 18, 'که څښتن ستا دا خوشحالي وویني ستا نه به ناراضه شي او د هغه نه به خپل غضب لېرې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_18.mp3', '', 1761754199, 1761754199),
(42827, 'Proverbs 24:19', 'Proverbs', 24, 19, 'د بدکارانو په خاطر اندېښنه مه کوه او د شر اچوونکو سره بخیلي مه کوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_19.mp3', '', 1761754199, 1761754199),
(42828, 'Proverbs 24:20', 'Proverbs', 24, 20, 'ځکه چې د بدکاره انسان دپاره د راتلونکې هیله نشته او د هغوی د ژوند ډېوه مخ په مړه کېدو ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_20.mp3', '', 1761754199, 1761754199),
(42829, 'Proverbs 24:21', 'Proverbs', 24, 21, 'نو ای زما زویه! د څښتن او له پاچا څخه وېره لره او د هغو خلکو ملګرتیا مه کوه چې له اطاعت کولو نه اووښتي دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_21.mp3', '', 1761754199, 1761754199),
(42830, 'Proverbs 24:22', 'Proverbs', 24, 22, 'ځکه چې مصیبت به په دوی ناڅاپه نازل شي او څوک پوهیږي چې هغوی به په دوی کوم ډول بلا نازله کړي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_22.mp3', '', 1761754199, 1761754199),
(42831, 'Proverbs 24:23', 'Proverbs', 24, 23, 'د حکمت خاوندانو دا خبرې هم کړې دي. د قضاوت په وخت کې د چا طرفداري ښه کار نه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_23.mp3', '', 1761754199, 1761754199),
(42832, 'Proverbs 24:24', 'Proverbs', 24, 24, 'هرڅوک چې مجرم ته وایي چې ته بې‌ګناه یې نو قومونه به پرې لعنت ووایي او ولسونه به ترې کرکه وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_24.mp3', '', 1761754199, 1761754199),
(42833, 'Proverbs 24:25', 'Proverbs', 24, 25, 'خو څوک چې مجرم ملامتوي نو بری او برکت به یې په برخه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_25.mp3', '', 1761754199, 1761754199),
(42834, 'Proverbs 24:26', 'Proverbs', 24, 26, 'څوک چې ښکاره او روښانه ځواب ورکوي لکه رښتینی ملګری چې څوک په مخ ښکلوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_26.mp3', '', 1761754199, 1761754199),
(42835, 'Proverbs 24:27', 'Proverbs', 24, 27, 'لومړی خپل کاروبار قوي کړه او ځمکه دې وکره او بیا خپل کور ودان کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_27.mp3', '', 1761754199, 1761754199),
(42836, 'Proverbs 24:28', 'Proverbs', 24, 28, 'له ثبوت پرته د بل چا په خلاف شاهدي مه ورکوه او هېڅکله د هغه په هکله د دروغو هڅه مه کوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_28.mp3', '', 1761754199, 1761754199),
(42837, 'Proverbs 24:29', 'Proverbs', 24, 29, 'او داسې مه وایه: «زما سره یې څه کړي دي زه به همداسې ورسره وکړم او خپل بدل به ترې واخلم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_29.mp3', '', 1761754199, 1761754199),
(42838, 'Proverbs 24:30', 'Proverbs', 24, 30, 'زه د یو لټ سړي په پټي تېر شوم او د یو ناپوهه سړي د انګورو باغ مې ولیده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_30.mp3', '', 1761754199, 1761754199),
(42839, 'Proverbs 24:31', 'Proverbs', 24, 31, 'چې په هرځای کې یې اغزي راختلي وو او ځمکه یې په هر ډول واښو پوښل شوې وه او د تیږو دېوالونه یې راغورځېدلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_31.mp3', '', 1761754199, 1761754199),
(42840, 'Proverbs 24:32', 'Proverbs', 24, 32, 'کله چې ما دا هرڅه وکتل نو په فکر کې ډوب شوم او څه چې ما ولیدل د هغې نه مې داسې عبرت واخیست:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_32.mp3', '', 1761754199, 1761754199),
(42841, 'Proverbs 24:33', 'Proverbs', 24, 33, 'که لټ سړی وایي: «نور به هم ویده شم او لاس به د سر لاندې کېږدم چې ارام وکړم»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_33.mp3', '', 1761754199, 1761754199),
(42842, 'Proverbs 24:34', 'Proverbs', 24, 34, 'نو غریبي به د داړه مار په شان په هغه راشي او نېستي به د وسله وال غل په څېر ورباندې یرغل وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs24_verse_34.mp3', '', 1761754199, 1761754199),
(42843, 'Jeremiah 45:1', 'Jeremiah', 45, 1, 'يرمياه نبى باروک د نيرياه زوئ ته د يهويقيم د يوسياه د زوئ د بادشاهۍ په څلورم کال چې د يهوداه بادشاه وو پېغام ورکړو د دې نه وروستو کله چې باروک په طومار کښې هغه څۀ وليکل کوم چې ورته يرمياه فرمائيلى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah45_verse_1.mp3', '', 1761754199, 1761754199),
(42844, 'Jeremiah 45:2', 'Jeremiah', 45, 2, '”اے باروکه، دا هغه څۀ دى چې مالِک خُدائ د بنى اِسرائيلو خُدائ پاک يې تاسو ته فرمائى چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah45_verse_2.mp3', '', 1761754199, 1761754199),
(42845, 'Jeremiah 45:3', 'Jeremiah', 45, 3, 'تا ووئيل چې افسوس دې په ما وى. زۀ د غمونو او تکليفونو د لاندې شوے يم. ولې زما دا دردونه کافى نۀ وُو څۀ؟ مالِک خُدائ زما په غمونو کښې اضافه وکړه. زۀ د اسويلو نه ستړے ستومانه شوے يم او هيڅ قسم آرام راته نۀ ملاويږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah45_verse_3.mp3', '', 1761754199, 1761754199),
(42846, 'Jeremiah 45:4', 'Jeremiah', 45, 4, 'باروکه، مالِک خُدائ داسې فرمائى چې، زۀ به دا قوم تباه کړم کوم چې ما آباد کړے دے. او څۀ چې ما کَرلى دى هغه به د بېخ نه راوباسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah45_verse_4.mp3', '', 1761754199, 1761754199),
(42847, 'Jeremiah 45:5', 'Jeremiah', 45, 5, 'ولې تۀ د خپل ځان دپاره د دې نه نور هم زيات د خاص سلوک اُميد کوې څۀ؟ داسې مۀ کوه. زۀ به لوئ افت په دې خلقو نازل کړم. خو تۀ چرته هم ځې نو زۀ به تا ته ستا ژوندون درکړم. مالِک خُدائ داسې فرمائى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah45_verse_5.mp3', '', 1761754199, 1761754199),
(42848, 'Jeremiah 4:1', 'Jeremiah', 4, 1, 'مالِک خُدائ فرمائى، ”اے بنى اِسرائيلو، کۀ چرې تاسو واپس ما له راتلل غواړئ نو ما له واپس راشئ. کۀ چرې تاسو خپل پليت بُتان زما د نظر نه اخوا کړئ او نور نۀ ګمراه کېږئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_1.mp3', '', 1761754199, 1761754199),
(42849, 'Jeremiah 4:2', 'Jeremiah', 4, 2, 'کله چې تاسو قسم خورئ چې، ”مالِک خُدائ ژوندے دے“ نو په رښتيا، اِنصاف، او صداقت سره خپله وعده پوره کوئ، نو بيا به تۀ د دُنيا قومونو ته د برکت ذريعه وګرځې او ټول قومونه به ستا په وجه زما نوم ته جلال ورکړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_2.mp3', '', 1761754199, 1761754199),
(42850, 'Jeremiah 4:3', 'Jeremiah', 4, 3, 'مالِک خُدائ د يهوداه او يروشلم خلقو ته فرمائى، ”د خپلو زړونو په سخته زمکه کښې يوه وکړئ او په ازغو کښې تخم مۀ کَرئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_3.mp3', '', 1761754199, 1761754199),
(42851, 'Jeremiah 4:4', 'Jeremiah', 4, 4, 'اے د يهوداه او د يروشلم خلقو خپل زړونه ما ته وقف کړئ، هسې نه ستاسو د بدو اعمالو په وجه زما د قهر اور بل شى نو هغه به تاسو مکمل وسوزوى او بيا به داسې هيڅ څوک نۀ وى چې هغه مړ کړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_4.mp3', '', 1761754199, 1761754199),
(42852, 'Jeremiah 4:5', 'Jeremiah', 4, 5, 'په يهوداه کښې اعلان وکړئ او يروشلم ته اِطلاع ورکړئ او ورته ووايئ، ”په ټول مُلک کښې بيګل وغږوئ. په زوره چغې ووهئ. او ورته ووايئ، راشئ، محفوظو ښارونو کښې پناه واخلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_5.mp3', '', 1761754199, 1761754199),
(42853, 'Jeremiah 4:6', 'Jeremiah', 4, 6, 'د صيون طرف ته د تېښتې دپاره جنډا اوچته کړئ او په منډه محفوظ ځائ ته وتښتئ. ځکه چې زۀ د شمال د خوا نه افت او سخته تباهى راولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_6.mp3', '', 1761754199, 1761754199),
(42854, 'Jeremiah 4:7', 'Jeremiah', 4, 7, 'د ځنګل د زمرى په شان د قومونو سخت او تباه کوونکے دشمن د خپل غار نه راووتو، هغه د خپل ځائ نه راروان دے چې ستاسو زمکه تباه کړى او ستاسو ښارونه به وران ويجاړ کړى او هغه به خالى پاتې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_7.mp3', '', 1761754199, 1761754199),
(42855, 'Jeremiah 4:8', 'Jeremiah', 4, 8, 'د ماتم او ټاټ جامې واغوندئ، ژړا او وير وکړئ. ځکه چې د مالِک خُدائ سخت قهر تر اوسه پورې په مونږ باندې دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_8.mp3', '', 1761754199, 1761754199),
(42856, 'Jeremiah 4:9', 'Jeremiah', 4, 9, 'مالِک خُدائ فرمائى، په هغه ورځ به بادشاهان او آفسران حوصله بائيلى، د اِمامانو به د يرې نه وېښتۀ ودريږى او پېغمبران به د يرې نه جام پاتې شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_9.mp3', '', 1761754199, 1761754199),
(42857, 'Jeremiah 4:10', 'Jeremiah', 4, 10, 'بيا ما ووئيل، ”اے قادر مطلق خُدايه، دا خلق او يروشلم ستا په هغه وينا دوکه شُو کومه چې تا کړې وه چې تاسو به پوره په امن کښې اوسېږئ، خو په دې کښې تُوره زمونږ د مرۍ دپاسه سوره شوه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_10.mp3', '', 1761754199, 1761754199),
(42858, 'Jeremiah 4:11', 'Jeremiah', 4, 11, 'په دغه وخت کښې به دې خلقو او يروشلم ته ووئيلے شى چې، ”زما عزيزانو. د صحرا د اوچتو غونډو نه به سوزونکى هوا په تاسو راشى، دا به هغه ښۀ هوا نۀ وى چې دانې د بوسو نه جدا کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_11.mp3', '', 1761754199, 1761754199),
(42859, 'Jeremiah 4:12', 'Jeremiah', 4, 12, 'خو زما د خوا نه به ډېره تېزه هوا لکه د طوفان راشى نو اوس زۀ خپله فېصله او سزا د ستاسو په خلاف اعلانوم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_12.mp3', '', 1761754199, 1761754199),
(42860, 'Jeremiah 4:13', 'Jeremiah', 4, 13, 'وګورئ، دشمن لکه د وريځو په شان زمونږ خوا ته راروان دے. د هغۀ جنګى ګاډۍ لکه د تېز طوفان په شان راروانې دى او د هغۀ آسونه د باز نه تېز دى. په مونږ افسوس، مونږ تباه او برباد شُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_13.mp3', '', 1761754199, 1761754199),
(42861, 'Jeremiah 4:14', 'Jeremiah', 4, 14, 'اے يروشلمه، خپل زړۀ د ګناه او شرارت نه ووينځه، نو دغه شان به تۀ خلاصون حاصل کړئ. ترڅو پورې به تۀ په خپل زړۀ کښې د ګناه سوچونه کوې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_14.mp3', '', 1761754199, 1761754199),
(42862, 'Jeremiah 4:15', 'Jeremiah', 4, 15, 'يو آواز د دان نه د بد خبر اعلان کوى او د اِفرائيم د غونډو نه د افت راتلو خبردارے ورکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_15.mp3', '', 1761754199, 1761754199),
(42863, 'Jeremiah 4:16', 'Jeremiah', 4, 16, 'د دُنيا غېر قومونو ته خبردارے ورکړه او يروشلم ته اعلان وکړه چې، ”ستاسو او د يهوداه د ښارونو خلاف د جنګ چغې وهونکے غټ لښکر د لرې مُلک نه راروان دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_16.mp3', '', 1761754199, 1761754199),
(42864, 'Jeremiah 4:17', 'Jeremiah', 4, 17, 'دوئ به يروشلم داسې محاصره کړى لکه چې سړى د پټى حفاظت کوى، ځکه چې د دې خلقو د مالِک خُدائ نه سرکشى کړې ده، مالِک خُدائ داسې فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_17.mp3', '', 1761754199, 1761754199),
(42865, 'Jeremiah 4:18', 'Jeremiah', 4, 18, 'اے يهوداه، ستا خپل چال چلن دا مصيبت په تا نازل کړے دے. دا ستا سزا ده. او دا څومره ترخه ده. او دا څومره زړۀ سورے کوونکې ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_18.mp3', '', 1761754199, 1761754199),
(42866, 'Jeremiah 4:19', 'Jeremiah', 4, 19, 'واى! واى! زۀ په درد او مصيبت کښې راګېر شوم. زړۀ مې درزيږى نور زۀ چپ پاتې کېدے نۀ شم. ځکه چې ما د دشمن د جنګ د بيګل آوازونه واورېدل او د دوئ د جنګ د ناروا شور آوازونه مې واورېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_19.mp3', '', 1761754199, 1761754199),
(42867, 'Jeremiah 4:20', 'Jeremiah', 4, 20, 'د تباهۍ او بربادۍ چپې پرله پسې په مُلک راخورې شوې، هر طرف ته مُلک تباه شو، ناګهانه زما خېمې تباه شوې، او په يوه لحظه کښې زما پناه ګاه تباه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_20.mp3', '', 1761754199, 1761754199),
(42868, 'Jeremiah 4:21', 'Jeremiah', 4, 21, 'ترڅو پورې به زۀ د جنګونو دا جنډې ګورم او ترڅو پورې به د بيګلو آوازونه اورم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_21.mp3', '', 1761754199, 1761754199),
(42869, 'Jeremiah 4:22', 'Jeremiah', 4, 22, 'مالِک خُدائ فرمائى، ”زما خلق کم عقل دى، هغوئ ما نۀ پېژنى. هغوئ لکه د ناپوهه ماشومانو په شان عقل نۀ لرى. په ورانى کښې ډېر پوهه دى خو په نېکۍ کولو نۀ پوهيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_22.mp3', '', 1761754199, 1761754199),
(42870, 'Jeremiah 4:23', 'Jeremiah', 4, 23, 'ما په زمکه باندې نظر واچولو زمکه خالى وه او هيڅ په کښې نۀ وُو، او چې آسمان ته مې وکتل نو هلته هم رڼا نۀ وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_23.mp3', '', 1761754199, 1761754199),
(42871, 'Jeremiah 4:24', 'Jeremiah', 4, 24, 'په غرونو باندې مې نظر واچولو نو دا خوځېدل او غونډو هم ټالونه خوړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_24.mp3', '', 1761754199, 1761754199),
(42872, 'Jeremiah 4:25', 'Jeremiah', 4, 25, 'ما هرې خوا ته وليدل خو څوک هم راته ښکاره نۀ شو، او ټول مارغان هم تښتېدلى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_25.mp3', '', 1761754199, 1761754199),
(42873, 'Jeremiah 4:26', 'Jeremiah', 4, 26, 'ما هغه زرخيزه پټى وليدل چې په شاړو بدل شوى وُو. او ښارونه وران ويجاړ شوى وُو، چې د مالِک خُدائ په يروونکې غصې سره چخڼى شوى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_26.mp3', '', 1761754199, 1761754199),
(42874, 'Jeremiah 4:27', 'Jeremiah', 4, 27, 'مالِک خُدائ فرمائى، ”ټوله زمکه به تباه شى خو زۀ به بيا هم دا په پوره توګه نۀ تباه کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_27.mp3', '', 1761754199, 1761754199),
(42875, 'Jeremiah 4:28', 'Jeremiah', 4, 28, 'نو په دې وجه به زمکه ماتم کوى، او بره آسمان به تک تور شى. ځکه چې ما دا وفرمائيل او د خپلې خبرې نه به وانۀ وړم. ما دا فېصله کړې ده دا به بدله نۀ کړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_28.mp3', '', 1761754199, 1761754199),
(42876, 'Jeremiah 4:29', 'Jeremiah', 4, 29, 'د ښار خلق چې د فوجيانو د آسونو او د غشو ليندو شور او درزار واورى نو تښتى. او هر يو کس ځنګلونو او غرونو ته پناه وړى او هر يو ښار به خالى شى او هيڅ څوک به پاتې نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_29.mp3', '', 1761754199, 1761754199),
(42877, 'Jeremiah 4:30', 'Jeremiah', 4, 30, 'اے تباه او لوټ شويه ښاره، تۀ اوس څۀ کوې؟ تۀ ولې سرې جامې اچوې او د سرو کالے استعمالوې او سترګې توروې؟ تۀ هسې فضول خپل ځان سينګاروې. ستا عاشقانو تۀ نامنظوره کړے يې او ستا نه نفرت کوى او هغوئ ستا وژل غواړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_30.mp3', '', 1761754199, 1761754199),
(42878, 'Jeremiah 4:31', 'Jeremiah', 4, 31, 'ما داسې ژړا واورېدله لکه چې د يوې ښځې د ماشوم د پېدا کېدو وخت وى، داسې زبيرګى وُو لکه څنګه چې يوه ښځه په وړومبى ماشوم کوى. زما لور صيون ژاړى او سلګۍ وهى، او خپل لاس يې د امداد دپاره اوږد کړے دے او وائى، ”افسوس په ما! زۀ تباه شوم او چې د خپلو قاتلانو د وړاندې تکه زېړه او بې‌وسه شوې يمه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah4_verse_31.mp3', '', 1761754199, 1761754199),
(42879, 'Psalms 10:1', 'Psalms', 10, 1, 'ای څښتنه ولې لېرې ته ودرېږې؟ د سختیو وخت کې ولې پټوې ځان؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_1.mp3', '', 1761754199, 1761754199),
(42880, 'Psalms 10:2', 'Psalms', 10, 2, 'کبرجن دي بدکاران او ځوروي دوی غریبان هغوی دې ګېر شي هغو نقشو کې چې جوړې کړې دي دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_2.mp3', '', 1761754199, 1761754199),
(42881, 'Psalms 10:3', 'Psalms', 10, 3, 'کوي فخر بدکاران په خپلو بدو خواهشاتو حریصان سپکوي څښتن ورته ښکنځلې کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_3.mp3', '', 1761754199, 1761754199),
(42882, 'Psalms 10:4', 'Psalms', 10, 4, 'هېڅ پروا د څښتن نه کړي بدکاران دوی له کبره کوي فکر چې خدای هېڅ دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_4.mp3', '', 1761754199, 1761754199),
(42883, 'Psalms 10:5', 'Psalms', 10, 5, 'تل کامیاب دي بدکاران خپلو کارو کې د دوی د پوهې نه اوچت دي قضاوتونه د خدای وهي ملنډې دوی په خپلو ټولو دښمنانو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_5.mp3', '', 1761754199, 1761754199),
(42884, 'Psalms 10:6', 'Psalms', 10, 6, 'خپلو زړونو کې دوی وایي: «نه لړزېږو مونږ هېڅکله په پېړیو کې ځورېږو نه هېڅکله»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_6.mp3', '', 1761754199, 1761754199),
(42885, 'Psalms 10:7', 'Psalms', 10, 7, 'خولې یې ډکې د لعنتونو، دروغو او اخطارونو او د ژبو په سرونو یې بدي او شرارت دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_7.mp3', '', 1761754199, 1761754199),
(42886, 'Psalms 10:8', 'Psalms', 10, 8, 'نژدې کلیو کې ځانونه پټوي بې‌ګناه خلک قتلوي پټو ځایونو کې د دوی سترګې د کم‌بختو څار کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_8.mp3', '', 1761754199, 1761754199),
(42887, 'Psalms 10:9', 'Psalms', 10, 9, 'د زمریانو په شان دوی کړي انتظار پټو ځایو کې دوی پراته وي انتظار کې د خوارانو دوی رانیسي او راکاږي دا خواران خپلو دامو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_9.mp3', '', 1761754199, 1761754199),
(42888, 'Psalms 10:10', 'Psalms', 10, 10, 'دي بې‌وزله قربانیان پراته ټوټې ټوټې دي مات کړي د بدکارو زور دا خلک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_10.mp3', '', 1761754199, 1761754199),
(42889, 'Psalms 10:11', 'Psalms', 10, 11, 'بدکاران خپلو ځانونو سره وایي: «خدای هېر کړي هغه ټول دي هغه سترګې پټې کړې ما به نه ویني هېڅکله»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_11.mp3', '', 1761754199, 1761754199),
(42890, 'Psalms 10:12', 'Psalms', 10, 12, 'راپاڅه ای څښتنه سزا ورکړه بدکارانو ته ای خدایه ته هېر نه کړې هغه خلک چې محتاج دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_12.mp3', '', 1761754199, 1761754199),
(42891, 'Psalms 10:13', 'Psalms', 10, 13, 'بدکاره خلک ولې خدای سپکوي؟ خپلو ځانونو سره داسې وایي: «هغه به ماته سزا نه راکوي»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_13.mp3', '', 1761754199, 1761754199),
(42892, 'Psalms 10:14', 'Psalms', 10, 14, 'خو ته ګورې او د خلکو تکلیفونه او غمونه وینې نو تل د مرستې ورکولو ته تیار یې خدایه سپاري مسکینان ځانونه تاته ته همېش د یتیمانو مددګار یې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_14.mp3', '', 1761754199, 1761754199),
(42893, 'Psalms 10:15', 'Psalms', 10, 15, 'کړه مات لاسونه د بدانو او بدکارو خلکو ته هغوی ته د بدیو سزا ورکړه چې نور ونه کړي دا کار په اینده کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_15.mp3', '', 1761754199, 1761754199),
(42894, 'Psalms 10:16', 'Psalms', 10, 16, 'تل ترتله به پاچا وي څښتن نور قومونه نابودیږي به د ځمکې د ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_16.mp3', '', 1761754199, 1761754199),
(42895, 'Psalms 10:17', 'Psalms', 10, 17, 'ته دعا اورې څښتنه، د خوارانو ورکوې د هغوی زړونو ته قوت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_17.mp3', '', 1761754199, 1761754199),
(42896, 'Psalms 10:18', 'Psalms', 10, 18, 'د یتیمانو، مظلومانو فریادونه اورې د دوی په حق کې قضاوت کوې ته چې فاني انسان یې نور ونه وېروي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms10_verse_18.mp3', '', 1761754199, 1761754199),
(42897, 'Exodus 19:3', 'Exodus', 19, 3, 'موسی د خدای سره د ملاقات دپاره غره ته وخوت. څښتن هغه ته د غره څخه غږ وکړ او ورته ویې ویل: «د یعقوب اولادې یعنې اسراییلیانو ته داسې ووایه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_3.mp3', '', 1761754199, 1761754199),
(42898, 'Exodus 19:4', 'Exodus', 19, 4, 'تاسو ولیدل چې ما په مصریانو باندې څه وکړل او څنګه مې تاسو لکه د عقاب په شان چې خپل بچیان په خپلو وزرونو باندې وړي، دلته خپل ځان ته راوستلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_4.mp3', '', 1761754199, 1761754199),
(42899, 'Exodus 19:5', 'Exodus', 19, 5, 'اوس که چېرې تاسو په وفادارۍ سره زما اطاعت وکړئ او زما په لوظ باندې ټینګ ودرېږئ، بیا به تاسو په ټولو قومونو کې زما ځانګړی قوم شئ. که څه هم دا ټوله نړۍ زما ده،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_5.mp3', '', 1761754199, 1761754199),
(42900, 'Exodus 19:6', 'Exodus', 19, 6, 'خو تاسو به زما دپاره کاهنان او سپېڅلی قوم اوسئ. دا هغه خبره ده چې ته یې باید اسراییلیانو ته ورسوې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_6.mp3', '', 1761754199, 1761754199),
(42901, 'Exodus 19:7', 'Exodus', 19, 7, 'نو موسی د غره څخه راښکته شو او د قوم مشران یې سره راټول کړل او څه چې څښتن ورته ویلي وو، هغوی ته یې بیان کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_7.mp3', '', 1761754199, 1761754199),
(42902, 'Exodus 19:8', 'Exodus', 19, 8, 'ټولو خلکو په یو اواز په ځواب کې وویل: «هرڅه چې څښتن ویلي دي، مونږ به په هغه باندې عمل وکړو.» نو موسی د هغوی ځواب بېرته څښتن ته راوړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_8.mp3', '', 1761754199, 1761754199),
(42903, 'Exodus 19:9', 'Exodus', 19, 9, 'څښتن موسی ته وویل: «زه به تاته په توره ورېځ کې راشم، نو کله چې زه ستا سره خبرې کوم، خلک به یې واوري او په تا باندې به اعتبار وکړي.» څه چې خلکو ویلي وو، موسی هغه څښتن ته وویل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_9.mp3', '', 1761754199, 1761754199),
(42904, 'Exodus 19:10', 'Exodus', 19, 10, 'څښتن موسی ته وویل: «خلکو ته ورشه او ورته ووایه چې نن او سبا خپل ځانونه د عبادت دپاره پاک کړي او باید خپل کالي ووینځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_10.mp3', '', 1761754199, 1761754199),
(42905, 'Exodus 19:11', 'Exodus', 19, 11, 'او په درېمه ورځ تیار اوسي. ځکه چې زه په هغه ورځ د ټولو خلکو په حضور کې د سینا غره ته راښکته کېږم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_11.mp3', '', 1761754199, 1761754199),
(42906, 'Exodus 19:12', 'Exodus', 19, 12, 'د غره ګردچاپېره حد وټاکه چې خلک ورڅخه تېر نه شي او هغوی ته ووایه: پام کوئ چې غره ته راونه خېژئ او حتی هغه ته نژدې هم ورنه شئ. که څوک په هغه باندې پښه کېږدي، نو وبه وژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_12.mp3', '', 1761754199, 1761754199),
(42907, 'Exodus 19:13', 'Exodus', 19, 13, 'هغه باید سنګسار شي او یا په غشو وویشتل شي او هېڅوک باید هغه ته لاس ورنه وړي. دا به په انسان او حیوان دواړو باندې عملي کیږي. خو کله چې سرنی ووهل شي، بیا خلک کولای شي چې د غره لمنې ته راشي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_13.mp3', '', 1761754199, 1761754199),
(42908, 'Exodus 19:14', 'Exodus', 19, 14, 'بیا موسی له غره څخه راښکته شو او خلکو ته یې وویل چې د عبادت دپاره تیار شي. نو هغوی خپل کالي ووینځل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_14.mp3', '', 1761754199, 1761754199),
(42909, 'Exodus 19:15', 'Exodus', 19, 15, 'او موسی خلکو ته وویل: «د درېمې ورځې دپاره ځانونه تیار کړئ او په دې موده کې ښځو ته مه ورنژدې کېږئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_15.mp3', '', 1761754199, 1761754199),
(42910, 'Exodus 19:16', 'Exodus', 19, 16, 'د درېمې ورځې په سهار تندر او برېښنا شوه او د غره په سر باندې یوه توره ورېځ راښکاره شوه او د سرني یو ډېر لوړ غږ واورېدل شو. ټول خلک چې په کمپ کې وو، د وېرې له لاسه ولړزېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus19_verse_16.mp3', '', 1761754199, 1761754199);